-- 20-fips.sql
--
-- HAND-MAINTAINED (this file is the source of truth: edit it directly; no generator writes it).
--
-- FIPS 199 and FIPS 200, the two standards that put a system into a baseline. FIPS 199
-- defines the three potential impact levels; FIPS 200 names the seventeen minimum security
-- requirement areas the control families answer. The catalog carries neither, and neither
-- standard has changed since it was published (FIPS 199 in 2004, FIPS 200 in 2006), so the
-- rows are written here from the published PDFs rather than retrieved and built.
--
-- Sources:
--   FIPS 199, https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.199.pdf, section 3, the
--     potential impact definitions and their amplification.
--     SHA-256 73d19f05f71e30f378050f178aa3943c38790bbae56c07f2b5708c5a1a90242f
--   FIPS 200, https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf, section 3, the
--     seventeen minimum security requirements.
--     SHA-256 107a9b9cdc8eccf37386aec28bbaf2dfaef5cfece17151ceabc3960423243a57
-- Written from the published PDFs and string-matched against both on 2026-10-28, from two
-- source files whose SHA-256 are
--   DR_FIPS199.csv b5b652dda659d9b9c1942a00a00cfd68e7164486f4268b2116f4ace4ce39eb0b
--   DR_FIPS200.csv f3a9ff5e4b76727b4663b5543a5ca536447f8bebcf2972656deeeb405628e475
--
-- Columns:
--   FipsImpactLevel: one row per level. rank orders the levels; effectPhrase is the words
--     FIPS 199 uses for the level; definitionText is the definition as published;
--     amplificationText is the amplification as published; pdfPage is the PDF page index the
--     definition is on.
--   Fips200Requirement: one row per area, keyed by the family that answers it. PM, PT and SR
--     have no row: FIPS 200 predates them. areaName is the area as FIPS 200 names it, which
--     for CA differs from the current family name. pdfPage is the PDF page index, and
--     deepLink is sourceUrl with that page as its anchor, so a reference can open on the
--     area.
--   pdfPage means the same thing in both tables: the page index inside the PDF file, which
--     a #page= anchor opens, not the number printed on the page.
--
-- The DataSource row records when the links were last checked, as the other hand-maintained
-- files do. The link check covers the rows: make check-seed-links SEED_FILES=20-fips.sql
--
-- Keep comments free of apostrophes and web addresses other than the two sources above: the
-- link check reads this file as a link list and skips only whole comment lines.

INSERT INTO "DataSource" ("id", "name", "type", "url", "authorityLevel", "lastCrawled", "isActive", "description", "createdById", "createdAt", "updatedAt")
VALUES ('dsrc_fips', 'fips 199 and 200', 'fips', NULL, 'reference'::"AuthorityLevel", '2026-11-04'::timestamp, true, 'FIPS 199 impact levels and FIPS 200 requirement areas, maintained by hand in 20-fips.sql; the two PDFs were checked and their pages read back on this date.', 'system_nist_gov', NOW(), NOW())
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "lastCrawled" = EXCLUDED."lastCrawled", "description" = EXCLUDED."description", "updatedAt" = NOW();

INSERT INTO "FipsImpactLevel" ("id", "rank", "effectPhrase", "definitionText", "amplificationText", "sourceUrl", "pdfPage")
VALUES
  ('LOW', 1, 'limited adverse effect', 'The loss of confidentiality, integrity, or availability could be expected to have a limited adverse effect on organizational operations, organizational assets, or individuals.', 'A limited adverse effect means that, for example, the loss of confidentiality, integrity, or availability might: (i) cause a degradation in mission capability to an extent and duration that the organization is able to perform its primary functions, but the effectiveness of the functions is noticeably reduced; (ii) result in minor damage to organizational assets; (iii) result in minor financial loss; or (iv) result in minor harm to individuals.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.199.pdf', 6),
  ('MODERATE', 2, 'serious adverse effect', 'The loss of confidentiality, integrity, or availability could be expected to have a serious adverse effect on organizational operations, organizational assets, or individuals.', 'A serious adverse effect means that, for example, the loss of confidentiality, integrity, or availability might: (i) cause a significant degradation in mission capability to an extent and duration that the organization is able to perform its primary functions, but the effectiveness of the functions is significantly reduced; (ii) result in significant damage to organizational assets; (iii) result in significant financial loss; or (iv) result in significant harm to individuals that does not involve loss of life or serious life threatening injuries.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.199.pdf', 6),
  ('HIGH', 3, 'severe or catastrophic adverse effect', 'The loss of confidentiality, integrity, or availability could be expected to have a severe or catastrophic adverse effect on organizational operations, organizational assets, or individuals.', 'A severe or catastrophic adverse effect means that, for example, the loss of confidentiality, integrity, or availability might: (i) cause a severe degradation in or loss of mission capability to an extent and duration that the organization is not able to perform one or more of its primary functions; (ii) result in major damage to organizational assets; (iii) result in major financial loss; or (iv) result in severe or catastrophic harm to individuals involving loss of life or serious life threatening injuries.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.199.pdf', 7);

INSERT INTO "Fips200Requirement" ("controlFamilyId", "sortOrder", "areaName", "requirementText", "sourceUrl", "pdfPage", "deepLink")
VALUES
  ('AC', 1, 'Access Control', 'Organizations must limit information system access to authorized users, processes acting on behalf of authorized users, or devices (including other information systems) and to the types of transactions and functions that authorized users are permitted to exercise.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 8, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=8'),
  ('AT', 2, 'Awareness and Training', 'Organizations must: (i) ensure that managers and users of organizational information systems are made aware of the security risks associated with their activities and of the applicable laws, Executive Orders, directives, policies, standards, instructions, regulations, or procedures related to the security of organizational information systems; and (ii) ensure that organizational personnel are adequately trained to carry out their assigned information security-related duties and responsibilities.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 8, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=8'),
  ('AU', 3, 'Audit and Accountability', 'Organizations must: (i) create, protect, and retain information system audit records to the extent needed to enable the monitoring, analysis, investigation, and reporting of unlawful, unauthorized, or inappropriate information system activity; and (ii) ensure that the actions of individual information system users can be uniquely traced to those users so they can be held accountable for their actions.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 8, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=8'),
  ('CA', 4, 'Certification, Accreditation, and Security Assessments', 'Organizations must: (i) periodically assess the security controls in organizational information systems to determine if the controls are effective in their application; (ii) develop and implement plans of action designed to correct deficiencies and reduce or eliminate vulnerabilities in organizational information systems; (iii) authorize the operation of organizational information systems and any associated information system connections; and (iv) monitor information system security controls on an ongoing basis to ensure the continued effectiveness of the controls.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 8, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=8'),
  ('CM', 5, 'Configuration Management', 'Organizations must: (i) establish and maintain baseline configurations and inventories of organizational information systems (including hardware, software, firmware, and documentation) throughout the respective system development life cycles; and (ii) establish and enforce security configuration settings for information technology products employed in organizational information systems.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 9, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=9'),
  ('CP', 6, 'Contingency Planning', 'Organizations must establish, maintain, and effectively implement plans for emergency response, backup operations, and post-disaster recovery for organizational information systems to ensure the availability of critical information resources and continuity of operations in emergency situations.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 9, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=9'),
  ('IA', 7, 'Identification and Authentication', 'Organizations must identify information system users, processes acting on behalf of users, or devices and authenticate (or verify) the identities of those users, processes, or devices, as a prerequisite to allowing access to organizational information systems.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 9, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=9'),
  ('IR', 8, 'Incident Response', 'Organizations must: (i) establish an operational incident handling capability for organizational information systems that includes adequate preparation, detection, analysis, containment, recovery, and user response activities; and (ii) track, document, and report incidents to appropriate organizational officials and/or authorities.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 9, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=9'),
  ('MA', 9, 'Maintenance', 'Organizations must: (i) perform periodic and timely maintenance on organizational information systems; and (ii) provide effective controls on the tools, techniques, mechanisms, and personnel used to conduct information system maintenance.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 9, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=9'),
  ('MP', 10, 'Media Protection', 'Organizations must: (i) protect information system media, both paper and digital; (ii) limit access to information on information system media to authorized users; and (iii) sanitize or destroy information system media before disposal or release for reuse.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 9, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=9'),
  ('PE', 11, 'Physical and Environmental Protection', 'Organizations must: (i) limit physical access to information systems, equipment, and the respective operating environments to authorized individuals; (ii) protect the physical plant and support infrastructure for information systems; (iii) provide supporting utilities for information systems; (iv) protect information systems against environmental hazards; and (v) provide appropriate environmental controls in facilities containing information systems.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 9, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=9'),
  ('PL', 12, 'Planning', 'Organizations must develop, document, periodically update, and implement security plans for organizational information systems that describe the security controls in place or planned for the information systems and the rules of behavior for individuals accessing the information systems.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 9, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=9'),
  ('PS', 13, 'Personnel Security', 'Organizations must: (i) ensure that individuals occupying positions of responsibility within organizations (including third-party service providers) are trustworthy and meet established security criteria for those positions; (ii) ensure that organizational information and information systems are protected during and after personnel actions such as terminations and transfers; and (iii) employ formal sanctions for personnel failing to comply with organizational security policies and procedures.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 9, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=9'),
  ('RA', 14, 'Risk Assessment', 'Organizations must periodically assess the risk to organizational operations (including mission, functions, image, or reputation), organizational assets, and individuals, resulting from the operation of organizational information systems and the associated processing, storage, or transmission of organizational information.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 9, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=9'),
  ('SA', 15, 'System and Services Acquisition', 'Organizations must: (i) allocate sufficient resources to adequately protect organizational information systems; (ii) employ system development life cycle processes that incorporate information security considerations; (iii) employ software usage and installation restrictions; and (iv) ensure that third-party providers employ adequate security measures to protect information, applications, and/or services outsourced from the organization.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 9, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=9'),
  ('SC', 16, 'System and Communications Protection', 'Organizations must: (i) monitor, control, and protect organizational communications (i.e., information transmitted or received by organizational information systems) at the external boundaries and key internal boundaries of the information systems; and (ii) employ architectural designs, software development techniques, and systems engineering principles that promote effective information security within organizational information systems.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 10, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=10'),
  ('SI', 17, 'System and Information Integrity', 'Organizations must: (i) identify, report, and correct information and information system flaws in a timely manner; (ii) provide protection from malicious code at appropriate locations within organizational information systems; and (iii) monitor information system security alerts and advisories and take appropriate actions in response.', 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf', 10, 'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.200.pdf#page=10');
